scripts.run:
:local a [/ip address find address="192.168.10.1/24" disabled=no]
:if ([:len $a] != 1) do={:put ("lan1 count=" . [:len $a])} else={
  :local i [/ip address get [:pick $a 0] interface]
  :put ("lan1 " . $i . " running=" . [/interface get [find name=$i] running])
}

:local a [/ip address find address="192.168.20.1/24" disabled=no]
:if ([:len $a] != 1) do={:put ("lan2 count=" . [:len $a])} else={
  :local i [/ip address get [:pick $a 0] interface]
  :put ("lan2 " . $i . " running=" . [/interface get [find name=$i] running])
}

:foreach s in={"telnet";"ftp";"www";"api"} do={
  :foreach i in=[/ip service find name=$s] do={:put ($s . " disabled=" . [/ip service get $i disabled])}
}
